#!/usr/bin/env bash
set -euo pipefail
policy=".motorlab/LAB_FIXED_DOWNLOADER_POLICY_V1.txt"
publisher=".github/scripts/publish-fixed-lab-downloader.sh"
workflow=".github/workflows/build-apks.yml"
test -s "$policy"
test -s "$publisher"
grep -Fxq 'AUTO_UPDATE_FIXED_LAB_URL=true' "$policy"
grep -Fxq 'PROMOTE_MAIN_MADRE_PRODUCTION=false' "$policy"
grep -Fxq 'PROTECTED_OLD_CODES=3875230,4768904,3938567' "$policy"
grep -Fxq 'CHANNEL_RELEASE_TAG=visionflix-lab-current' "$policy"
grep -Fxq 'CHANNEL_ASSET=Verlezza-Vision-TV.apk' "$policy"
grep -Fq 'REQUIRE_VERSION_MONOTONIC=true' "$policy"
grep -Fq 'REQUIRE_FINAL_PUBLIC_DOWNLOAD_CHECKSUM=true' "$policy"
bash -n "$publisher"
grep -Fq 'sha256sum --status -c LAB-APK-SHA256SUMS.txt' "$publisher"
grep -Fq 'if (( code <= old_code ))' "$publisher"
grep -Fq 'gh release download "$immutable"' "$publisher"
grep -Fq 'Verlezza-Vision-TV-INCOMING-$run_id.apk' "$publisher"
grep -Fq 'gh api -X PATCH' "$publisher"
grep -Fq -- '--prerelease --latest=false' "$publisher"
grep -Fq 'group: visionflix-lab-fixed-downloader-channel' "$workflow"
grep -Fq 'cancel-in-progress: false' "$workflow"
echo '[FIXED_DOWNLOADER_CONFIG_TESTS=PASS] LAB-only, signed, monotonic, staged, rollback-ready'
